  const cir = (cx, cy, r, c) => ell(cx, cy, r, r, c);
  const legs = (list, c, w = 5) => list.map(p => `<polyline points="${p}" fill="none" stroke="#000" stroke-opacity=".5" stroke-width="${w + 3.5}" stroke-linecap="round" stroke-linejoin="round"/>`).join('') + list.map(p => `<polyline points="${p}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`).join('') + list.map(p => `<polyline points="${p}" fill="none" stroke="#000" stroke-opacity=".28" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" transform="translate(0,1.5)" stroke-dasharray="0 0"/><polyline points="${p}" fill="none" stroke="#fff" stroke-opacity=".32" stroke-width="${w * .35}" stroke-linecap="round" stroke-linejoin="round" transform="translate(0,-${w * .28})"/>`).join('');
