  S.groundTex = (h) => { const a = h % 97, b = (h >> 5) % 89, d = (h >> 9) % 83; return `<ellipse cx="${20 + a}" cy="${30 + b}" rx="${44 + d % 24}" ry="${8 + a % 6}" ${dk(.08)}/><ellipse cx="${100 - b}" cy="${90 - d % 60}" rx="${38 + a % 20}" ry="${7 + b % 5}" ${lt(.09)}/><ellipse cx="${60 + d % 30}" cy="${64 + a % 30}" rx="${30 + b % 20}" ry="${5 + d % 4}" ${dk(.05)}/><path d="M${10 + a % 40} ${100 - b % 30}l4-12M${60 + b % 50} ${40 + d % 60}l3-11M${30 + d % 60} ${60 + a % 40}l5-10M${80 + a % 40} ${110 - b % 40}l3-12" stroke="#000" stroke-opacity=".13" stroke-width="3" stroke-linecap="round"/>`; };
  // Ground variant tints: base, dry (warmer), lush (deeper), dust (paler). Chosen by low-frequency noise so patches are 3–8 cells wide.
