  S.groundExtra = (h) => { const k = h % 23; if (k === 0) return `<ellipse cx="${30 + (h >> 3) % 60}" cy="${40 + (h >> 7) % 50}" rx="${36 + (h >> 4) % 24}" ry="${12 + (h >> 6) % 8}" fill="#7A5A3C" fill-opacity=".22"/><ellipse cx="${30 + (h >> 3) % 60}" cy="${38 + (h >> 7) % 50}" rx="${22 + (h >> 4) % 16}" ry="${6 + (h >> 6) % 4}" fill="#7A5A3C" fill-opacity=".18"/>`; if (k === 1) return [0, 1, 2, 3].map(i => `<circle cx="${20 + ((h >> (i * 3)) % 90)}" cy="${20 + ((h >> (i * 5 + 1)) % 90)}" r="${4 + i % 3}" fill="#A8A399" ${OL}/>`).join(''); if (k === 2) return [0, 1, 2].map(i => `<circle cx="${24 + ((h >> (i * 4)) % 80)}" cy="${24 + ((h >> (i * 6 + 2)) % 80)}" r="6" fill="#6E9A4E" fill-opacity=".7"/>`).join(''); return ''; };
  S.earth = (c, o = .35) => `<rect width="128" height="128" fill="${c}" fill-opacity="${o}"/>`;
  S.waterDeep = (c) => `<rect width="128" height="128" fill="${c}"/><rect width="128" height="128" fill="#0B2540" fill-opacity=".28"/><ellipse cx="44" cy="40" rx="30" ry="6" fill="#fff" fill-opacity=".07"/><ellipse cx="90" cy="86" rx="26" ry="5" fill="#fff" fill-opacity=".06"/><path d="M20 62q16-4 36 0M70 30q12-3 30 0" fill="none" stroke="#fff" stroke-opacity=".14" stroke-width="3" stroke-linecap="round"/>`;
  S.water = (c) => `<rect width="128" height="128" fill="${c}"/><rect width="128" height="128" fill="url(#mx-water)"/><path d="M12 42q14-6 28 0t28 0t28 0t20 0" fill="none" stroke="#fff" stroke-opacity=".3" stroke-width="4" stroke-linecap="round"/><path d="M34 88q14-6 28 0t28 0" fill="none" stroke="#fff" stroke-opacity=".22" stroke-width="4" stroke-linecap="round"/><path d="M8 66q10-4 20 0M90 70q10-4 24 0" fill="none" stroke="#fff" stroke-opacity=".16" stroke-width="3" stroke-linecap="round"/>`;
