  // Nest wall — organic soil ridge. Neighbour mask nb={n,s,e,w} lets runs merge into one bulging bank; ends are rounded. `h` seeds the lumps.
  S.wall = (c, ghost, h = 0, nb = { e: true, w: true }) => { const dark = mix(c, '#1A0A14', .45), light = mix(c, '#E8A5C4', .3); const p = (k) => (h >> k) % 13; const le = nb.w ? 74 : 54 + p(1) % 6, re = nb.e ? 74 : 54 + p(3) % 6, te = nb.n ? 72 : 52 + p(5) % 6, be = nb.s ? 70 : 50 + p(7) % 6; const cx = 64 + (re - le) / 2, rx = (le + re) / 2, cy = 64 - H / 2 + (be - te) / 2, ry = (te + be) / 2 - 6; const lumps = [[cx - rx * .45 + p(2), cy - ry * .35 + p(4) % 7, 26 + p(6) % 8, 17 + p(8) % 5], [cx + rx * .4 - p(9), cy + ry * .1 + p(11) % 7, 28 + p(1) % 8, 18 + p(3) % 5], [cx - rx * .1 + p(5) % 9, cy + ry * .45 - p(7) % 7, 24 + p(10) % 8, 15 + p(12) % 5]]; const shapes = [[cx, cy, rx, ry], ...lumps]; const draw = (fill, extra = '') => shapes.map(q => `<ellipse cx="${q[0]}" cy="${q[1]}" rx="${q[2]}" ry="${q[3]}" fill="${fill}" ${extra}/>`).join(''); const fcy = cy + H * .62, fshapes = [[cx, fcy, rx * .96, ry * .9], [cx - rx * .4, fcy + 8, 30, 20], [cx + rx * .35, fcy + 6 + p(2) % 5, 32, 22]]; const fdraw = (fill, extra = '') => fshapes.map(q => `<ellipse cx="${q[0]}" cy="${q[1]}" rx="${q[2]}" ry="${q[3]}" fill="${fill}" ${extra}/>`).join(''); const veins = `M${cx - rx * .8} ${cy + ry * .2}q${rx * .3} -${ry * .5} ${rx * .7} -${ry * .1}t${rx * .8} ${ry * .4}M${cx - rx * .5} ${cy + ry * .6}q${rx * .4} -${ry * .3} ${rx * .9} ${ry * .1}M${cx - rx * .6} ${fcy + 6}q${rx * .5} 10 ${rx * 1.1} -2`; const nod = [[cx - rx * .35 + p(1) % 9, cy - ry * .2 + p(3) % 7], [cx + rx * .4 - p(5) % 9, cy + ry * .35], [cx + rx * .05 + p(7) % 9, cy - ry * .55]]; const spikes = [[cx - rx * .55 + p(2) % 9, cy - ry * .1, -20], [cx + rx * .5 - p(4) % 9, cy + ry * .2, 15], [cx + rx * .1 + p(6) % 7, cy + ry * .55, 0]]; return `<g${ghost ? ' opacity=".55"' : ''}>${cast(H, .2)}${fdraw(dark, OL)}${fdraw(dark)}${fdraw('url(#mx-front)')}${fdraw('url(#mx-under)', 'opacity=".7"')}${muscle(`M${cx - rx * .7} ${fcy + 12}q${rx * .35} -8 ${rx * .7} 2t${rx * .7} -3`, 5)}${draw(c, OL)}${draw(c)}${draw('url(#mx-top)')}${lumps.map(q => `<ellipse cx="${q[0]}" cy="${q[1]}" rx="${q[2]}" ry="${q[3]}" fill="url(#mx-sph)" opacity=".7"/>`).join('')}<path d="${veins}" fill="none" stroke="${C.flesh}" stroke-width="4" stroke-linecap="round"/><path d="${veins}" fill="none" stroke="#fff" stroke-opacity=".18" stroke-width="1.5" stroke-linecap="round" transform="translate(0,-1)"/><ellipse cx="${cx}" cy="${cy + ry * .55}" rx="${rx * .9}" ry="${ry * .4}" fill="url(#mx-under)" opacity=".5"/><ellipse cx="${cx - rx * .3}" cy="${cy - ry * .45}" rx="${rx * .4}" ry="${ry * .22}" fill="${light}" fill-opacity=".28"/>${nod.map(q => `<circle cx="${q[0]}" cy="${q[1]}" r="6" fill="${C.glow}" fill-opacity=".85" ${OL}/><circle cx="${q[0]}" cy="${q[1]}" r="11" fill="${C.glow}" fill-opacity=".18"/><circle cx="${q[0] - 2}" cy="${q[1] - 2}" r="2" fill="#fff" fill-opacity=".7"/>`).join('')}${spikes.map(q => `<g transform="rotate(${q[2]} ${q[0]} ${q[1]})">${blade(`M${q[0] - 6} ${q[1]}q6-26 12-34q-2 20-0 34z`)}</g>`).join('')}${ghost ? `<ellipse cx="${cx}" cy="${cy}" rx="${rx - 6}" ry="${ry - 6}" fill="none" stroke="#fff" stroke-opacity=".7" stroke-width="4" stroke-dasharray="14 10"/>` : ''}</g>`; };
